<?php
require __DIR__.'/../../config/bootstrap.php';
use Pharmacy\Auth\Authorization;use Pharmacy\Doctors\DoctorRepository;use Pharmacy\Support\Csrf;
Authorization::requireRole('ADMIN','PHARMACIST');$repo=new DoctorRepository($pdo);$message=$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){Authorization::requireRole('ADMIN');try{Csrf::validate((string)($_POST['csrf']??''));$repo->save(['name'=>trim($_POST['name']??''),'specialization'=>trim($_POST['specialization']??''),'registration_no'=>trim($_POST['registration_no']??''),'phone'=>trim($_POST['phone']??''),'visiting_schedule'=>trim($_POST['visiting_schedule']??''),'active'=>1]);$message='Doctor saved.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$repo->active();$title='Visiting Doctors';require __DIR__.'/../../templates/header.php';?>
<h2 class="page-title">Visiting Doctors</h2><?php if($message):?><div data-flash="<?=htmlspecialchars($message)?>"></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<div class="row g-3"><div class="col-lg-4"><?php if(Authorization::hasRole('ADMIN')):?><div class="card"><div class="card-body"><h5>Add Doctor</h5><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(Csrf::token())?>"><?php foreach(['name'=>'Doctor Name','specialization'=>'Specialization','registration_no'=>'Registration No.','phone'=>'Phone','visiting_schedule'=>'Visiting Schedule'] as $n=>$l):?><div class="mb-2"><label class="form-label"><?=$l?></label><input class="form-control" name="<?=$n?>" <?=$n==='name'?'required':''?>></div><?php endforeach;?><button class="btn btn-dark">Save</button></form></div></div><?php endif;?></div><div class="col-lg-8"><div class="card"><div class="card-body"><table class="table datatable"><thead><tr><th>Name</th><th>Specialization</th><th>Registration</th><th>Schedule</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['specialization']??'')?></td><td><?=htmlspecialchars($r['registration_no']??'')?></td><td><?=htmlspecialchars($r['visiting_schedule']??'')?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require __DIR__.'/../../templates/footer.php';
